node -e "
const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';
const sender = 'alice';
const recipient = 'bob';
const subject = 'High Priority: Onboarding Equipment Setup Needed';
const content = \`Hello Bob,

I'm writing to request your assistance with an onboarding equipment setup for a newly onboarded contractor who is starting soon. As outlined in Olivia's original request to Ethan, the following items need to be arranged before start of business on the next business day:

1. Standard Windows laptop — provisioned and ready for use
2. VPN access — configured and credentials provided
3. Email account — set up and fully operational

Please prioritize this request to ensure the contractor has everything they need from day one.

Let me know if you have any questions or need additional details.

Best regards\`;

// Build the .eml content
const eml = [
  'Content-Type: text/plain; charset=\"utf-8\"',
  'Content-Transfer-Encoding: 7bit',
  'MIME-Version: 1.0',
  'From: ' + sender + '@example.com',
  'To: ' + recipient + '@example.com',
  'Subject: ' + subject,
  '',
  content
].join('\n');

// Ensure directories exist
for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  const filePath = path.join(dir, subject + '.eml');
  fs.writeFileSync(filePath, eml);
}

console.log('Successfully sent email to ' + recipient + '.');
"
